// Each entry is [display name, optional ASCII romanization]. These are
// representative synthetic name pools, not population rankings or personal records.
// Split and normalize handles once on worker startup; rows only index a profile.
const ASCII_LETTERS = { đ: 'd', ł: 'l', ø: 'o', ß: 'ss', æ: 'ae', œ: 'oe', ð: 'd', þ: 'th', ı: 'i' };
const nameEntry = entry => {
    const [display, handle = display] = entry.split('~');
    const ascii = handle.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/[đłøßæœðþı]/g, char => ASCII_LETTERS[char]).replace(/[^a-z0-9]+/g, '.').replace(/^\.|\.$/g, '');
    return [display, ascii];
};
const namePool = text => text.split('|').map(nameEntry);
const nameProfile = (first, last, familyFirst = false, separator = ' ') => ({
    firstNames: namePool(first), lastNames: namePool(last), familyFirst, separator,
});

